// Server-backed research. The market simulation is separately and explicitly labeled.
let apiReady=false,serverItems=[],pollHandle=null;
const researchHistory=read('kimpscope-research-v2',{}),busySymbols=new Set();
async function api(path,body){const r=await fetch('/api/'+path,body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{});if(!r.ok){let msg='서버 요청에 실패했습니다.';try{msg=(await r.json()).detail||msg}catch{}throw Error(msg)}return r.json()}
function saveResearch(){try{localStorage.setItem('kimpscope-research-v2',JSON.stringify(researchHistory))}catch{}}
async function status(){try{const s=await api('status');apiReady=true;$('#backend-status').textContent=`메타데이터 ${s.items}건 / 색인 ${s.indexed}건 / 문서 청크 ${s.chunks}건 · ${s.message} · ${s.llm_ready?'생성 모델 설정됨':'모델 키 미설정 — 임베딩 검색·생성 사용 불가'}`;$('#index-action').disabled=s.state==='indexing';if(s.state==='indexing'&&!pollHandle)pollHandle=setInterval(status,3000);if(s.state!=='indexing'&&pollHandle){clearInterval(pollHandle);pollHandle=null}}catch{apiReady=false;$('#backend-status').textContent='검색 서버 미연결 · 로컬 Python 서버 실행이 필요합니다. 시세표는 시뮬레이션입니다.'}}
$('#index-action').onclick=async()=>{try{$('#index-action').disabled=true;await api('index');await status()}catch(e){$('#backend-status').textContent=e.message;$('#index-action').disabled=false}};
function referenceModal(doc){$('#modal-body').innerHTML=`<h2>${esc(doc.title)}</h2><p>${esc(doc.source_type||'문서')}</p><p>거래소: ${esc(doc.exchange||'원문 참고')} · 게시: ${esc(doc.published_at||'미상')} · 개정: ${esc(doc.revision||doc.updated_at||'미상')}</p><p>${esc(doc.text||doc.body||'')}</p>`;if(/^https:\/\//.test(doc.source||'')){const a=document.createElement('a');a.href=doc.source;a.target='_blank';a.rel='noopener noreferrer';a.className='source-link';a.textContent='원문 확인 ↗';$('#modal-body').append(a)}$('#modal').showModal()}
renderChat=function(){const symbol=selected.symbol;$('#chat-scope').textContent=`${selected.name} (${symbol}) · 코인별 대화`;
 const rows=Array.isArray(researchHistory[symbol])?researchHistory[symbol]:[];
 $('#messages').innerHTML=rows.length?rows.map((m,index)=>`<div class="message ${m.role==='user'?'user':'answer'}">${esc(m.text)}${(m.citations||[]).map((d,i)=>`<button data-evidence="${index}:${i}:citation">[${d.number}] ${esc(d.title)}</button>`).join('')}${(m.evidence||[]).length?'<div class="muted">검색 결과 · 답변 인용 아님</div>'+m.evidence.map((d,i)=>`<button data-evidence="${index}:${i}:search">${esc(d.title)}</button>`).join(''):''}${m.role!=='user'&&!m.citations?.length?'<div class="muted">생성 답변의 인용 문서 없음</div>':''}</div>`).join(''):`<div class="welcome">${esc(selected.name)}에 대한 근거를 검색합니다.<small>선택 코인의 메타데이터를 항상 포함하며, 문서 밖 정보는 확인할 수 없다고 안내합니다.</small></div>`;
 if(busySymbols.has(symbol))$('#messages').insertAdjacentHTML('beforeend','<div class="message">문서 준비 · 의미 검색 · 답변 처리 중…</div>');$('#chat-form button').disabled=busySymbols.has(symbol);$('#clear').disabled=busySymbols.has(symbol);$('#messages').scrollTop=$('#messages').scrollHeight};
ask=async function(q){const c={...selected};if(!q.trim()||busySymbols.has(c.symbol))return;researchHistory[c.symbol]=Array.isArray(researchHistory[c.symbol])?researchHistory[c.symbol]:[];researchHistory[c.symbol].push({role:'user',text:q.slice(0,1000)});busySymbols.add(c.symbol);$('#question').value='';renderChat();try{const r=await api('query',{symbol:c.symbol,question:q,k:Number($('#top-k').value),mode:$('#retrieval-mode').value});researchHistory[c.symbol].push({role:'assistant',text:r.answer+`\n\n처리 ${(r.elapsed_ms/1000).toFixed(1)}초 · ${r.cache_hit?'수집 캐시 사용':'문서 준비 완료'}`+(r.collection?`\n검색어: ${(r.collection.keywords||[]).join(', ')} · 색인 ${(r.collection.selected||[]).length}건 · 제외 ${(r.collection.discarded||[]).length}건`:''),citations:r.citations,evidence:r.status==='missing_key'?r.evidence:[]})}catch(e){researchHistory[c.symbol].push({role:'assistant',text:e.message,citations:[]})}finally{busySymbols.delete(c.symbol);saveResearch();if(selected.symbol===c.symbol)renderChat();status()}};
$('#messages').onclick=e=>{const b=e.target.closest('[data-evidence]');if(!b)return;const [m,i,kind]=b.dataset.evidence.split(':');const row=researchHistory[selected.symbol][Number(m)];referenceModal((kind==='citation'?row.citations:row.evidence)[Number(i)])};
$('#clear').onclick=()=>{researchHistory[selected.symbol]=[];saveResearch();renderChat()};
let currentDocs=[];
renderNotices=async function(){const symbol=selected.symbol;$('#notices').innerHTML='<div class="empty">문서 목록 확인 중…</div>';try{const d=await api('documents/'+encodeURIComponent(symbol));if(selected.symbol!==symbol)return;currentDocs=d;$('#notices').innerHTML=d.map((doc,i)=>`<button class="notice" data-real-doc="${i}"><span class="notice-symbol">≡</span><span><b>${esc(doc.title)}</b><small>${esc(doc.source_type)} · ${doc.collected_at?esc(doc.collected_at.slice(0,10)):'메타데이터 스냅샷'}</small></span><span>↗</span></button>`).join('')}catch{if(selected.symbol===symbol)$('#notices').innerHTML='<div class="empty">검색 서버 연결 후 문서를 확인할 수 있습니다.</div>'}};
$('#notices').onclick=e=>{const b=e.target.closest('[data-real-doc]');if(b)referenceModal(currentDocs[Number(b.dataset.realDoc)])};
$('#explore').onsubmit=async e=>{e.preventDefault();const q=$('#condition').value;if(!q.trim())return;$('#explore-result').textContent='조건 해석 및 필터링 중…';try{const r=await api('explore',{query:q});serverItems=r.items;$('#explore-result').innerHTML=`${esc(r.message)} · 적용 조건 ${esc(JSON.stringify(r.conditions))}<br>`+r.items.map((x,i)=>`<button data-result="${i}">${esc(x.name)} · ${esc(x.symbol)}</button>`).join('')}catch(e){$('#explore-result').textContent=e.message}};
$('#explore-result').onclick=e=>{const b=e.target.closest('[data-result]');if(!b)return;const x=serverItems[Number(b.dataset.result)],existing=coins.find(c=>c.symbol===x.symbol);if(existing)selectCoin(x.symbol);else{selected={...x,index:0,color:'#64748b',glyph:x.symbol[0]};$('#selected-name').innerHTML=`<b>${esc(x.name)} · ${esc(x.symbol)}</b>`;$('#detail-price').textContent='시세 미연결';$('#up-price').textContent='—';$('#bin-price').textContent='—';$('#chart').innerHTML='';renderNotices();renderChat()}$('.assistant').scrollIntoView({behavior:'smooth',block:'center'})};
const originalDetail=renderDetail;renderDetail=function(){if(Number.isFinite(selected.usd))originalDetail()};
$('#checklist').onclick=()=>ask('선택 코인의 전송 전에 확인할 네트워크와 수수료 관련 사항을 근거가 있는 내용만 정리해줘. 현재 입출금 가능 여부는 추측하지 마.');
$('#about').onclick=()=>showModal('KimpScope · 데이터 범위','시세표는 업비트와 Binance 공개 API를 5초 간격으로 조회합니다. 실제 거래소 메타데이터 298건과 공식 문서 검색은 Python 서버가 담당합니다.\n\n다국어 임베딩·Chroma 검색·LangGraph 파이프라인을 사용합니다. API 키는 임베딩 검색과 답변 생성에 필요합니다. 키 없이 시세와 저장된 원문은 확인할 수 있습니다.\n\n대화 기록은 현재 브라우저에 저장됩니다. 로그인·실거래·공용 커뮤니티는 구현 범위에 포함하지 않았습니다.');
$('.notices .pill').textContent='SOURCE DOCUMENTS';$('.notices .muted').textContent='공식 문서 · 원문 확인';$('.chat-disclaimer').textContent='문서 수집 시점과 현재 상태는 다를 수 있습니다. 투자 조언을 대체하지 않습니다.';
status();renderNotices();renderChat();
clearInterval(demoTimer);
let liveSnapshot=null,livePaused=false,marketBusy=false;
$('.filters>span').textContent='시세 연결 확인 중';
$('.ticker>span').textContent='시세 연결 중';
$('.ticker>span:nth-child(2)').innerHTML='USD / KRW <b>—</b><small>환율 확인 중</small>';
$('.table-footer').innerHTML='<span>공개 API · 5초 간격 조회</span><span>김프 = (국내가 / (해외 USDT가 × 원/달러) − 1) × 100</span>';
$('#pause').onclick=()=>{livePaused=!livePaused;$('#pause').textContent=livePaused?'▶ 갱신 재개':'Ⅱ 갱신 일시정지';$('.ticker>span').textContent=livePaused?'갱신 일시정지':'시세 연결 확인 중';if(!livePaused)loadMarket()};
const oldTable=renderTable;
renderTable=function(){oldTable();if(!liveSnapshot){$('#coins').innerHTML='<tr><td colspan="6" class="empty">실제 시세를 수신하기 전에는 가격을 표시하지 않습니다.</td></tr>';return}document.querySelectorAll('#coins tr').forEach(tr=>{const c=coins.find(c=>c.symbol===tr.querySelector('[data-coin]')?.dataset.coin);if(!c)return;tr.children[1].textContent=money(c.domestic);tr.children[2].textContent=money(c.converted);tr.children[5].innerHTML='<span class="muted">'+(liveSnapshot.stale?'지연':'수신')+'</span>';if(!Number.isFinite(c.premium))tr.children[3].textContent='환율 미확보'})};
renderDetail=function(){const c=selected;$('#selected-name').innerHTML=`<div class="coin-select">${icon(c)}</div>`;if(!liveSnapshot||!Number.isFinite(c.domestic)){$('#detail-price').textContent='시세 미수신';$('#up-price').textContent='—';$('#bin-price').textContent='—';return}$('#detail-price').innerHTML=`₩ ${money(c.domestic)}<small>김치 프리미엄 ${liveSnapshot.stale?'산출 보류':Number.isFinite(c.premium)?pct(c.premium):'환율 미확보'}</small>`;$('#up-price').textContent='₩ '+money(c.domestic);$('#bin-price').textContent=c.foreign.toLocaleString('en-US',{maximumFractionDigits:4})+' USDT';loadChart();$('.detail-note').textContent=`${liveSnapshot.fx_label} ${money(liveSnapshot.fx)} KRW · USDT ${money(liveSnapshot.usdt_krw)} KRW(테더 프리미엄 ${pct(liveSnapshot.tether_premium)}). 현재가는 체결가이며 실제 체결 가능 가격·전송 비용은 포함하지 않습니다.`};
async function loadMarket(){if(livePaused||marketBusy)return;marketBusy=true;try{const r=await api('market');if(!r.rows.length)throw Error(r.source);liveSnapshot=r;r.rows.forEach(x=>Object.assign(coins.find(c=>c.symbol===x.symbol)||{},x));const age=Date.now()-r.received_at;r.stale=r.stale||age>15000;$('.ticker>span').textContent=r.stale?'시세 지연 · 프리미엄 확인 주의'+(r.error?' ('+r.error+')':''):'공개 시세 수신 · 5초 조회';$('.ticker>span:nth-child(2)').innerHTML=`USD / KRW <b>${money(r.fx)}</b><small>${r.fx?r.fx_source+' '+r.fx_date:'환율 미확보'} · 테더 ${pct(r.tether_premium)}</small>`;$('.filters>span').textContent=`수신 ${new Date(r.received_at).toLocaleTimeString('ko-KR',{hour12:false})}`;const priced=r.rows.filter(c=>Number.isFinite(c.premium));$('#avg').innerHTML=r.stale||!priced.length?'—':pct(priced.reduce((sum,c)=>sum+c.premium,0)/priced.length);$('#btc').textContent='₩ '+money(coins[0].domestic);$('.metrics .green').textContent=pct(coins[0].change)+' · 24H';const high=priced.reduce((a,c)=>a&&a.premium>c.premium?a:c,null);$('#highest').textContent=r.stale||!high?'—':high.symbol+' '+pct(high.premium);renderTable();renderDetail();if(r.stale)document.querySelectorAll('#coins tr').forEach(tr=>{if(tr.children[3])tr.children[3].textContent='지연'})}catch{ $('.ticker>span').textContent='실제 시세 미연결';$('.filters>span').textContent='수신 실패 · 가상 가격으로 대체하지 않음';$('#avg').textContent='—';$('#btc').textContent='—';$('#highest').textContent='—';liveSnapshot=null;renderTable();renderDetail()}finally{marketBusy=false}}
$('.chart-head>span').textContent='프리미엄 이력';$('#ranges').hidden=true;$('.chart-labels').hidden=true;$('.metrics .green').textContent='수신 대기';$('#chart').innerHTML='<div class="empty">과거 시세 미수집</div>';
$('#method').onclick=()=>showModal('출처와 계산 기준','국내 현재가: 업비트 공개 API\n해외 현재가: Binance 공개 API, USDT 마켓\n환산 기준: 원/달러 기준 환율 (한국수출입은행 매매기준율, 키가 없으면 Frankfurter 공개 기준환율 · 일 단위 고시값)\n\n김치 프리미엄 = (국내 현재가 / (해외 USDT 현재가 × 원/달러) − 1) × 100\n테더 프리미엄 = (업비트 USDT/KRW / 원/달러 − 1) × 100. USDT를 1달러로 보는 가정의 오차입니다.\n환율을 받지 못하면 김프를 표시하지 않습니다.\n\n5초 간격 REST 조회이며 거래소 간 수신 시각은 동일하지 않습니다. 시세 지연 시 프리미엄을 보류합니다. 실제 주문 체결가, 수수료, 전송 지연은 포함하지 않습니다. 차트는 업비트 국내 가격 캔들 종가입니다. 역사적 프리미엄 차트가 아닙니다.');
renderTable();renderDetail();loadMarket();setInterval(loadMarket,5000);
let chartKey='',chartBusy=false;
async function loadChart(){if(chartBusy||!selected?.symbol)return;const key=selected.symbol+range;if(key===chartKey)return;chartBusy=true;const symbol=selected.symbol;try{const data=await fetch('/api/candles/'+encodeURIComponent(symbol)+'?period='+range).then(r=>{if(!r.ok)throw Error();return r.json()});if(selected.symbol!==symbol)return;chartKey=key;const prices=data.map(d=>d.price),lo=Math.min(...prices),hi=Math.max(...prices),span=hi-lo||1;const path=prices.map((p,i)=>(i?'L':'M')+(i*270/Math.max(prices.length-1,1)).toFixed(1)+','+(140-(p-lo)/span*120).toFixed(1)).join(' ');$('#chart').innerHTML=`<svg viewBox="0 0 280 160" role="img" aria-label="${esc(symbol)} 업비트 실제 캔들 종가"><path d="M0 20 H280 M0 80 H280 M0 140 H280" stroke="#e2e7ef" stroke-dasharray="3 3"/><path d="${path}" fill="none" stroke="#245ad6" stroke-width="2"/></svg>`;$('.chart-labels').hidden=false;$('.chart-labels').innerHTML=`<span>${esc(data[0]?.time.slice(5,16)||'')}</span><span>${esc(data.at(-1)?.time.slice(5,16)||'')} KST</span>`}catch{$('#chart').innerHTML='<div class="empty">가격 이력을 불러오지 못했습니다.</div>'}finally{chartBusy=false}}
$('.chart-head>span').textContent='업비트 가격 · 캔들 종가';$('#ranges').hidden=false;
$('#ranges').onclick=e=>{const b=e.target.closest('[data-range]');if(!b)return;range=b.dataset.range;document.querySelectorAll('[data-range]').forEach(x=>x.classList.toggle('active',x===b));chartKey='';loadChart()};
